import{_ as n,o as i,c as a,a5 as h}from"./chunks/framework.Bf1r8NYr.js";const p=JSON.parse('{"title":"Bài 2 — Thu thập dữ liệu: ALCOA+, GCP và EDC","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-2-collection/index.md","filePath":"course/module-2-collection/index.md"}'),c={name:"course/module-2-collection/index.md"};function o(r,t,e,l,u,g){return i(),a("div",null,[...t[0]||(t[0]=[h('<h1 id="bai-2-—-thu-thap-du-lieu-alcoa-gcp-va-edc" tabindex="-1">Bài 2 — Thu thập dữ liệu: ALCOA+, GCP và EDC <a class="header-anchor" href="#bai-2-—-thu-thap-du-lieu-alcoa-gcp-va-edc" aria-label="Permalink to &quot;Bài 2 — Thu thập dữ liệu: ALCOA+, GCP và EDC&quot;">​</a></h1><p><strong>Mục tiêu:</strong> giải thích được ALCOA+; phân biệt được thu thập tốt và thu thập chỉ “đủ dùng”.</p><h2 id="noi-dung-chinh" tabindex="-1">Nội dung chính <a class="header-anchor" href="#noi-dung-chinh" aria-label="Permalink to &quot;Nội dung chính&quot;">​</a></h2><p>Lớp kiểm soát bảo mật, đạo đức và pháp lý áp dụng xuyên suốt mọi giai đoạn của vòng đời dữ liệu.</p><p>Dữ liệu nghiên cứu lâm sàng phải đáng tin trước tòa, trước hội đồng đạo đức và trước tạp chí. Khung cổ điển là <strong>ALCOA</strong> — Attributable (quy được cho ai), Legible (đọc được), Contemporaneous (ghi ngay lúc xảy ra), Original (bản gốc), Accurate (chính xác). <strong>ALCOA+</strong> thêm Complete (đầy đủ), Consistent (nhất quán), Enduring (bền vững), Available (truy xuất được). Một số hướng dẫn thêm Traceable (truy vết được) thành ALCOA++.</p><p><strong>ICH E6(R3) Good Clinical Practice</strong> (Step 4, 06/01/2025) là chuẩn GCP hiện hành, với 11 nguyên tắc. Annex 1 có mục mới về data governance và hệ thống máy tính — điều mà bản R2 không có. Thu thập hiện nay chủ yếu qua <strong>EDC (Electronic Data Capture)</strong> như REDCap: biểu mẫu điện tử có kiểm tra giá trị ngay khi nhập, có audit trail ghi ai sửa gì, khi nào.</p><p>Ba sai lầm phổ biến ở bước này:</p><ol><li><strong>Ghi sau, ghi hộ, ghi lại từ trí nhớ</strong> — vi phạm Contemporaneous và Attributable.</li><li><strong>Sửa dữ liệu không để lại dấu vết</strong> — vi phạm Original và Traceable; mọi sửa đổi phải có lý do và audit trail.</li><li><strong>Kiểm tra chất lượng 100% thủ công</strong> — tốn kém mà không tăng chất lượng tương xứng; xu hướng hiện nay là <strong>Risk-Based Quality Management (RBQM)</strong>: tập trung kiểm tra vào dữ liệu và quy trình rủi ro cao nhất.</li></ol><p><strong>Điểm cần nhớ:</strong> dữ liệu tốt không phải dữ liệu không có lỗi, mà là dữ liệu mà mọi lỗi đều được phát hiện, ghi lại và xử lý có thể truy vết.</p>',9)])])}const d=n(c,[["render",o]]);export{p as __pageData,d as default};
